INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q3711', 'Belgrado', 'belgrado', 'https://pt.wikipedia.org/wiki/Belgrado', 'Belgrado ) é a capital e maior cidade da Sérvia, e está localizada entre dois cursos de água internacionais, na confluência dos rios Danúbio e Sava, no norte da Sérvia, onde a planície da Panônia se limita com a região da península balcânica. Com uma população de 1 710 000 habitantes (2007), Belgrado é a maior cidade no território da ex-Iugoslávia, a segunda maior cidade sobre o rio Danúbio, bem como a quarta maior do Sudeste da Europa, após Istambul, Atenas e Bucareste.', 'aprovada' FROM `categorias` WHERE `chave` = 'lugar';
