INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q805', 'Iémen', 'iemen', 'https://pt.wikipedia.org/wiki/I%C3%A9men', 'Iémen (português europeu) ou Iêmen (português brasileiro) é um país árabe que ocupa a extremidade sudoeste da Península da Arábia. É limitado a norte pela Arábia Saudita, a leste por Omã, a sul pelo mar da Arábia e pelo golfo de Adem, do outro lado do qual se estende a costa da Somália e a oeste pelo estreito de Babelmândebe, que o separa de Jibuti, e pelo mar Vermelho, que providencia uma ligação à Eritreia. Além do território continental, o Iémen inclui também algumas ilhas situadas ao largo do Corno de África, das quais a maior é Socotorá. A capital e cidade mais populosa do país é Saná.', 'aprovada' FROM `categorias` WHERE `chave` = 'lugar';
