INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q221479', 'Gilberto Gil', 'gilberto gil', 'https://pt.wikipedia.org/wiki/Gilberto_Gil', 'Gilberto Passos Gil Moreira é um cantor, compositor, músico, político e escritor brasileiro. Com uma carreira de mais de seis décadas, é conhecido por sua relevante contribuição na música brasileira e por ser vencedor de prêmios Grammy Awards, Grammy Latino e galardoado pelo governo francês com a Ordem Nacional do Mérito (1997). Em 1999, foi nomeado \"Artista pela Paz\", pela UNESCO.', 'aprovada' FROM `categorias` WHERE `chave` = 'pessoa';
